import React from 'react';import {createRoot} from 'react-dom/client';import {BrowserRouter} from 'react-router-dom';
import StenoCard from '../../src/components/Sidebar/Stenocard.jsx';import AdminPanel from '../../src/components/AdminPanel.jsx';import {adminFetch} from '../../src/components/adminFetch.js';
const results=[];const check=(name,pass)=>results.push({name,pass:!!pass});const sleep=ms=>new Promise(r=>setTimeout(r,ms));const wait=async fn=>{const end=Date.now()+8000;while(Date.now()<end){if(fn())return;await sleep(30)}throw Error('wait timeout')};
let mic=0,utterance=null;const alerts=[];window.alert=m=>alerts.push(m);Object.defineProperty(navigator,'mediaDevices',{configurable:true,value:{getUserMedia:async()=>{mic++;throw Error('must not request microphone for disabled provider')}}});
window.SpeechRecognition=class{start(){this.onstart?.();window.__native=this;}stop(){this.onend?.()}};
const root=createRoot(document.getElementById('root'));root.render(<StenoCard onSpeechInput={e=>utterance=e}/>);
(async()=>{try{
await wait(()=>document.querySelector('button'));document.querySelector('button').click();await wait(()=>window.__native);check('production English uses native speech without Deepgram microphone or credentials',mic===0&&window.__native.lang==='en-IN'&&alerts.length===0);window.__native.stop();await sleep(30);
const select=document.querySelector('select');select.value='hi';select.dispatchEvent(new Event('change',{bubbles:true}));await sleep(50);window.__native=null;document.querySelector('button').click();await wait(()=>window.__native);check('production Hindi uses hi-IN browser fallback',window.__native.lang==='hi-IN');window.__native.onresult({resultIndex:0,results:[Object.assign([{transcript:'synthetic native words'}],{isFinal:true})]});check('production native speech still emits identified finals',utterance?.text==='synthetic native words'&&!!utterance.id);window.__native.stop();await sleep(30);
document.querySelector('button').click();await sleep(30);window.__native.onerror({error:'network'});await wait(()=>document.body.textContent.includes('could not connect'));check('native network failure stops cleanly with non-blocking retry guidance',document.querySelector('button').textContent.includes('Start Speaking'));
document.querySelector('button').click();await sleep(30);window.__native.onerror({error:'language-not-supported'});await wait(()=>document.body.textContent.includes('selected language is unavailable'));check('unsupported language preserves retry and typing fallback',document.querySelector('button').textContent.includes('Start Speaking'));
document.querySelector('button').click();await sleep(30);window.__native.onerror({error:'not-allowed'});await wait(()=>document.body.textContent.includes('Microphone permission denied'));check('microphone denial is visible without a blocking alert',alerts.length===0&&document.querySelector('button').textContent.includes('Start Speaking'));
delete window.SpeechRecognition;delete window.webkitSpeechRecognition;document.querySelector('button').click();await wait(()=>document.body.textContent.includes('Browser speech is unavailable'));check('unsupported browser shows non-blocking typing fallback',alerts.length===0&&document.body.textContent.includes('continue typing'));
let rejected=false;try{await adminFetch('/users')}catch{rejected=true}check('admin browser client fails closed without session',rejected);
sessionStorage.setItem('tnt_draft_session','a'.repeat(64));const response=await adminFetch('/users');const users=await response.json();check('verified admin session lists safe user fields',users[0].fullName==='SyntheticCustomer'&&!Object.hasOwn(users[0],'password'));
sessionStorage.setItem('tnt_draft_session','b'.repeat(64));rejected=false;try{await adminFetch('/users')}catch{rejected=true}check('normal account cannot use admin browser client',rejected);
sessionStorage.setItem('tnt_draft_session','a'.repeat(64));localStorage.setItem('user',JSON.stringify({_id:'1',role:'admin'}));root.render(<BrowserRouter><AdminPanel/></BrowserRouter>);await wait(()=>document.body.textContent.includes('SyntheticCustomer'));check('real administrator panel loads with verified session',true);
}catch(e){check('completed: '+e.message,false)}document.body.innerHTML='<pre id="verification-result"></pre>';document.getElementById('verification-result').textContent=JSON.stringify(results)})();
